"""Generate docs/errors.md from `src/blackbox/errors.py` (run after any registry change)."""
from __future__ import annotations

import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(ROOT / "src"))

from blackbox import errors


def main() -> None:
    lines = ["# Error codes", "",
             "Generated by `tools/gen_errors_doc.py` from `src/blackbox/errors.py`. `blackbox doctor` prints the",
             "same table, so a code in a log line always has a next step attached to it.", "",
             "| Code | Meaning | What to do |", "|---|---|---|"]
    for code, (message, remedy) in sorted(errors.REGISTRY.items()):
        lines.append(f"| `{code}` | {message} | {remedy} |")
    lines += ["", f"{len(errors.REGISTRY)} codes.", ""]
    (ROOT / "docs" / "errors.md").write_text("\n".join(lines), encoding="utf-8")
    print(f"wrote docs/errors.md ({len(errors.REGISTRY)} codes)")


if __name__ == "__main__":
    main()
